// Parity test: the TypeScript port must reproduce the ORIGINAL WordPress PHP
// calculator's output exactly. golden.json is generated by test/php-golden.php
// (run `php web/test/php-golden.php > web/test/golden.json` to regenerate).

import { describe, it, expect } from 'vitest';
import golden from './golden.json';
import { calculate } from '../lib/calculator';
import { getConstants } from '../lib/config';
import type { CalcInput } from '../lib/types';

const constants = getConstants();

interface GoldenCase {
  input: CalcInput;
  result: Record<string, unknown>;
}

const cases = golden as unknown as Record<string, GoldenCase>;

// Recursive compare: numbers within a tiny epsilon (rounded outputs should match
// to the bit, but epsilon guards against last-bit float noise); strings exact.
function closeEqual(actual: unknown, expected: unknown, path: string): void {
  if (typeof expected === 'number') {
    expect(typeof actual, `${path} should be a number`).toBe('number');
    expect(
      Math.abs((actual as number) - expected),
      `${path}: got ${String(actual)}, expected ${expected}`
    ).toBeLessThan(1e-6);
  } else if (Array.isArray(expected)) {
    expect(Array.isArray(actual), `${path} should be an array`).toBe(true);
    const arr = actual as unknown[];
    expect(arr.length, `${path} length`).toBe(expected.length);
    expected.forEach((v, i) => closeEqual(arr[i], v, `${path}[${i}]`));
  } else if (expected !== null && typeof expected === 'object') {
    const obj = actual as Record<string, unknown>;
    for (const k of Object.keys(expected as Record<string, unknown>)) {
      closeEqual(obj[k], (expected as Record<string, unknown>)[k], `${path}.${k}`);
    }
  } else {
    expect(actual, path).toBe(expected);
  }
}

describe('calculator parity with the WordPress PHP implementation', () => {
  for (const [name, c] of Object.entries(cases)) {
    it(`matches PHP for "${name}"`, () => {
      const result = calculate(c.input, constants);
      closeEqual(result as unknown, c.result, name);
    });
  }
});
